// ELF Header (Ehdr)
// File layout and initial metadata
typedef struct {
    unsigned char e_ident[EI_NIDENT]; // Magic, Class (32/64 bit), Endianness
    uint16_t e_type;                  // ET_REL (Object), ET_EXEC (Exec), ET_DYN (Shared)
    uint16_t e_machine;               // Architecture (EM_X86_64)
    Elf64_Addr e_entry;               // Program entry point VMA
    Elf64_Off e_shoff;                // Section Header table offset
    Elf64_Off e_phoff;                // Program Header table offset
} Elf64_Ehdr;

// Symbol Table Entry (Sym)
// Used by linker for name resolution and address assignment
typedef struct {
    Elf64_Word st_name;   // Offset into the String Table (.strtab)
    unsigned char st_info; // Binding (Global, Local) and Type (Func, Obj)
    Elf64_Half st_shndx;  // Section index (e.g., .text, .data)
    Elf64_Addr st_value;  // Address/Offset relative to section start
    Elf64_Xword st_size;  // Size of the object
} Elf64_Sym;

// Relocation Entry (Rel)
// Specifies locations that need address fixing during linking
typedef struct {
    Elf64_Addr r_offset; // Location within the section requiring adjustment
    Elf64_Xword r_info;  // Index of the target symbol + Relocation Type
} Elf64_Rel;

// Program Header (Phdr) - Load View
// Specifies how segments are mapped into memory at runtime
typedef struct {
    Elf64_Word p_type;    // Segment type (PT_LOAD is loadable)
    Elf64_Off p_offset;   // Offset in file
    Elf64_Addr p_vaddr;   // Target Virtual Memory Address
    Elf64_Xword p_filesz; // Size of data in file
    Elf64_Xword p_memsz;  // Size required in memory (memsz >= filesz for .bss)
    Elf64_Word p_flags;   // Access permissions (R, W, X)
} Elf64_Phdr;
